(#{item.fileId}, #{item.uploadId}, #{item.userId}, #{item.videoId}, #{item.fileIndex}, #{item.fileName}, #{item.fileSize}, #{item.filePath}, #{item.updateType}, #{item.transferResult}, #{item.duration})
